import math
    import random
    import time

    LANGUAGE_WRAPPER = "A rigid three-leg stand has a top joint that fixes the angle between any two legs to be equal and constant. Initially, the three legs all have length {leg_length}, and when the stand is set on level ground, the top is {initial_height} units above the ground. Later, the lower {broken_one} units of one leg and the lower {broken_two} units of another leg break off; the third leg remains intact. The stand is set up again on level ground with the joint's pairwise-angle constraint unchanged from the original setting. Let h be the new height of the top above the ground. Compute floor({scale} * h)."

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate a nontrivial instance where two legs are shortened.
# Constraints:
# - leg_length L in [7, 20]
# - initial_height H0 in [3, L-2]
# - broken_one, broken_two positive and distinct, both < L-1
# - Computed height h is valid and not near-integer multiples when scaled
import math
for _ in range(1000):
    L = rng.randint(8, 20)
    H0 = rng.randint(3, L-2)
    # Ensure H0/L is not extreme (avoid c too close to -1/2 or 1)
    z0 = H0 / L
    c = 1.5 * (z0 ** 2) - 0.5
    if not (-0.45 < c < 0.95):
        continue
    # choose broken amounts
    b1 = rng.randint(1, max(2, L-3))
    b2 = rng.randint(1, max(2, L-3))
    if b1 == b2:
        # encourage asymmetry
        if b2 < L-3:
            b2 += 1
        else:
            b2 -= 1
    if b1 <= 0 or b2 <= 0:
        continue
    if b1 >= L or b2 >= L:
        continue
    Ls = [L - b1, L - b2, L]
    if min(Ls) <= 1:
        continue
    # Compute height using derived formula:
    # S = sum(1/Li), w = (h*S)/(1+2c);
    # A_i = 1/Li - c*S/(1+2c);
    # D = sum(A_i^2)/(1-c) + c*S^2/(1+2c)^2; then h = 1/sqrt(D)
    S = sum(1.0 / Li for Li in Ls)
    denom = 1.0 + 2.0 * c
    if denom <= 1e-12:
        continue
    A = [1.0 / Li - c * S / denom for Li in Ls]
    sum_A2 = sum(a * a for a in A)
    if (1.0 - c) <= 1e-12:
        continue
    D = sum_A2 / (1.0 - c) + c * (S * S) / (denom * denom)
    if D <= 0:
        continue
    h = 1.0 / math.sqrt(D)
    # sanity checks
    if not (0.1 < h < min(Ls) - 1e-9):
        continue
    # choose scale to avoid trivial rounding and enforce difficulty
    scale = rng.randint(80, 500)
    val = scale * h
    frac = abs(val - round(val))
    if frac < 1e-6:
        continue
    # Slight additional difficulty: ensure both broken amounts are not 1 simultaneously
    if b1 == 1 and b2 == 1:
        continue
    return {
        'leg_length': L,
        'initial_height': H0,
        'broken_one': b1,
        'broken_two': b2,
        'scale': scale
    }
# Fallback deterministic safe instance if random attempts fail
return {
    'leg_length': 12,
    'initial_height': 7,
    'broken_one': 3,
    'broken_two': 2,
    'scale': 200
}

    def verifier(assign):
# Recompute answer from first principles.
# Use exact rationals where possible, and high-precision Decimal for sqrt.
from fractions import Fraction
from decimal import Decimal, getcontext
import math
# Validate slots
try:
    L = int(assign['leg_length'])
    H0 = int(assign['initial_height'])
    b1 = int(assign['broken_one'])
    b2 = int(assign['broken_two'])
    scale = int(assign['scale'])
except Exception:
    # invalid types
    return (False, None)
if not (L >= 3 and 1 <= H0 < L and 1 <= b1 < L and 1 <= b2 < L):
    # domain invalid
    return (False, None)
if scale <= 0:
    return (False, None)
# new lengths
Ls = [L - b1, L - b2, L]
if min(Ls) <= 0:
    return (False, None)
# Compute c from original configuration: c = (3/2)*(H0/L)^2 - 1/2
z0 = Fraction(H0, L)
c = Fraction(3, 2) * (z0 * z0) - Fraction(1, 2)
# Check c in valid range to avoid degeneracy
if c >= 1 or c <= Fraction(-1, 2):
    return (False, None)
# Compute S, A_i, and D in exact rationals
S = sum(Fraction(1, Li) for Li in Ls)
denom = Fraction(1, 1) + 2 * c
if denom == 0:
    return (False, None)
A = [Fraction(1, Li) - c * S / denom for Li in Ls]
sum_A2 = sum(a * a for a in A)
if (Fraction(1, 1) - c) == 0:
    return (False, None)
D = sum_A2 / (Fraction(1, 1) - c) + c * (S * S) / (denom * denom)
if D <= 0:
    return (False, None)
# Compute h = 1/sqrt(D) using high precision
getcontext().prec = 80
D_dec = Decimal(D.numerator) / Decimal(D.denominator)
h_dec = (Decimal(1) / D_dec.sqrt())
# sanity: h less than all leg lengths
for Li in Ls:
    if h_dec >= Decimal(Li):
        return (False, None)
# Return floor(scale * h)
ans_dec = Decimal(scale) * h_dec
# Ensure not NaN/Inf
if not (ans_dec.is_finite()):
    return (False, None)
# Floor
# Decimal quantize to floor: use to_integral_value with rounding toward -inf
from decimal import ROUND_FLOOR
ans_int = int(ans_dec.to_integral_value(rounding=ROUND_FLOOR))
return (True, ans_int)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

